def prime_fib(n: int):
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.
    >>> prime_fib(1)
    2
    >>> prime_fib(2)
    3
    >>> prime_fib(3)
    5
    >>> prime_fib(4)
    13
    >>> prime_fib(5)
    89
    """
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        if num < 9:
            return True
        r = int(num ** 0.5)
        for i in range(3, r + 1, 2):
            if num % i == 0:
                return False
        return True

    def generate_fib():
        a, b = 0, 1
        while True:
            yield a
            a, b = b, a + b

    count = 0
    for fib in generate_fib():
        if is_prime(fib):
            count += 1
            if count == n:
                return fib
