def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    # Find all prime factors and their counts
    primes = []
    temp = a
    factor_count = 0

    for i in range(2, a + 1):
        while temp % i == 0:
            if is_prime(i):
                factor_count += 1
                primes.append(i)
            temp //= i
        if factor_count > 3:
            break

    # Check if there are exactly 3 prime factors (could be same or different primes)
    if factor_count == 3 and temp == 1:
        return True
    else:
        return False
