def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    # Check if a can be written as the product of exactly 3 primes (with repetition allowed)
    if a < 2:
        return False

    # Find all prime factorizations with exactly 3 factors (counting multiplicity)
    for p1 in range(2, a + 1):
        if not is_prime(p1):
            continue
        for p2 in range(2, a // p1 + 1):
            if not is_prime(p2):
                continue
            product2 = p1 * p2
            if product2 > a:
                break
            if a % product2 != 0:
                continue
            p3 = a // product2
            if p1 * p2 * p3 == a and is_prime(p3):
                return True

    return False
